import placements from '../../data/placements.json'

export { placements }

/**
 * Reuse the first object of an original prop model, cloned at the SF positions
 * generated by scripts/sf/build.mjs (sources/data/placements.json).
 * Each entry: [ x, y, z, rotationY, scale ]
 */
export function relocate(children, list)
{
    const base = children[0]

    return list.map(([ x, y, z, rotationY = 0, scale = 1 ], index) =>
    {
        const clone = base.clone()
        clone.name = `${base.name.replace(/[.0-9]+$/, '')}.${String(index).padStart(3, '0')}`
        clone.position.set(x, y, z)
        clone.rotation.set(0, rotationY, 0)
        clone.scale.setScalar(scale)
        clone.updateMatrix()
        clone.updateMatrixWorld(true)
        return clone
    })
}
